{
  "name": "EPICS过程变量记录器",
  "name_en": "EPICS Process Variable Logger",
  "manufacturer": "",
  "description": "一种用于实验控制系统的监测与记录软件组件，用来跟踪EPICS过程变量（PV）的连接状态、数值变化、描述信息和时间戳，并将这些数据写入日志或数据队列，便于实验运行记录、状态审计和后续分析。",
  "description_en": "A monitoring and logging software component for laboratory control systems that tracks EPICS process variables (PVs), including connection status, value changes, descriptions, and timestamps, and writes them to logs or data queues for run records, status auditing, and later analysis.",
  "tag_hints": [
    "EPICS PV logging",
    "control system monitoring",
    "process variable history",
    "timestamped data logging",
    "experimental run records"
  ],
  "actions": [
    {
      "action_name": "auto-write",
      "description": "写入一条PV日志文本记录。",
      "description_en": "Write a text record to the PV log."
    },
    {
      "action_name": "auto-flush",
      "description": "刷新并强制输出当前缓存的日志数据。",
      "description_en": "Flush and force out any buffered log data."
    },
    {
      "action_name": "auto-set_mdel",
      "description": "设置PV日志记录的监测死区或变化阈值。",
      "description_en": "Set the monitor deadband or change threshold for PV logging."
    },
    {
      "action_name": "auto-set_desc",
      "description": "设置PV的描述信息。",
      "description_en": "Set the description for the PV."
    },
    {
      "action_name": "auto-onConnect",
      "description": "处理PV连接状态变化事件。",
      "description_en": "Handle a PV connection status change event."
    },
    {
      "action_name": "auto-onChanges",
      "description": "处理PV数值变化事件并记录新数据。",
      "description_en": "Handle a PV value change event and record the new data."
    },
    {
      "action_name": "auto-save_current_value",
      "description": "保存PV当前数值及当前时间戳。",
      "description_en": "Save the current PV value together with the current timestamp."
    },
    {
      "action_name": "auto-write_data",
      "description": "将已收集的PV数据写入输出记录。",
      "description_en": "Write the collected PV data to the output record."
    }
  ]
}

